window.FRAG = {"header": "<header class=\"header\" data-sid=\"mainHeader\">\n  <div class=\"header-left\">\n    <a href=\"/trial/en/\" class=\"logo-link\">\n      <img src=\"assets/brand/moni-logo.svg\" alt=\"Moní\" class=\"logo-img light-logo\">\n      <img src=\"assets/brand/moni-logo.svg\" alt=\"Moní\" class=\"logo-img dark-logo\">\n    </a>\n  </div>\n\n  <!-- Desktop Navigation -->\n  <nav class=\"site-nav\" data-sid=\"siteNav\">\n    <a href=\"/trial/en/\" class=\"nav-link active\">Home</a>\n        <a href=\"/trial/en/about\" class=\"nav-link\">About the Project</a>\n        <a href=\"/trial/en/news\" class=\"nav-link\">News</a>\n  </nav>\n\n  <div class=\"header-actions\">\n    <!-- Language switcher -->\n    <div style=\"position:relative;\">\n    <button class=\"hdr-btn lang-switch-btn\" data-sid=\"langBtn\">\n      <span data-sid=\"langLabel\">EN</span>\n      <svg class=\"lang-arrow\" data-sid=\"langArrow\" width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"></polyline></svg>\n    </button>\n    <div class=\"lang-dropdown\" data-sid=\"langDropdown\">\n            <button class=\"\">RU</button>\n            <button class=\"selected\">EN <span class=\"check\">✓</span></button>\n            <button class=\"\">TJ</button>\n          </div>\n    </div>\n\n    <!-- Theme toggle -->\n    <button class=\"hdr-btn theme-toggle\" data-sid=\"themeBtn\" title=\"Theme\">\n      <div class=\"theme-icon\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\">\n          <circle class=\"theme-circle\" cx=\"12\" cy=\"12\" r=\"5\" fill=\"currentColor\"></circle>\n          <g class=\"theme-rays\"><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"23\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"4.22\" y1=\"4.22\" x2=\"6.34\" y2=\"6.34\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"17.66\" y1=\"17.66\" x2=\"19.78\" y2=\"19.78\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"1\" y1=\"12\" x2=\"4\" y2=\"12\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"20\" y1=\"12\" x2=\"23\" y2=\"12\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"4.22\" y1=\"19.78\" x2=\"6.34\" y2=\"17.66\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line><line x1=\"17.66\" y1=\"6.34\" x2=\"19.78\" y2=\"4.22\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"></line></g>\n          <circle class=\"theme-mask\" cx=\"18\" cy=\"6\" r=\"6\" fill=\"var(--bg-primary)\"></circle>\n        </svg>\n      </div>\n    </button>\n\n    <!-- Account -->\n            <a class=\"acct-login-btn\" href=\"/trial/en/login\">Log in</a>\n    \n    <!-- Burger (mobile) -->\n    <button class=\"burger-btn\" data-sid=\"burgerBtn\" aria-label=\"Menu\">\n      <span></span><span></span><span></span>\n    </button>\n  </div>\n</header>", "sbToggle": "<button class=\"sb-toggle\" data-sid=\"sbToggle\" aria-label=\"История чатов\" title=\"История чатов\">\n  <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg>\n</button>", "welcome": "<div class=\"welcome\" data-sid=\"welcomeScreen\">\n  <div class=\"welcome-title\">Need lawyer?<br>Ask Moní first</div>\n  <div class=\"welcome-sub\">Tajik law, made simple with AI</div>\n  <div class=\"mode-bar\" data-sid=\"modeBar\">\n    <button class=\"mode-btn active\" data-mode=\"simple\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg> <span>Send</span></button>\n    <button class=\"mode-btn\" data-mode=\"calculate\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"4\" y=\"2\" width=\"16\" height=\"20\" rx=\"2\"></rect><line x1=\"8\" y1=\"6\" x2=\"16\" y2=\"6\"></line><line x1=\"8\" y1=\"10\" x2=\"10\" y2=\"10\"></line><line x1=\"14\" y1=\"10\" x2=\"16\" y2=\"10\"></line></svg> <span>Calculator</span></button>\n  </div>\n  <div class=\"input-wrap centered\" data-sid=\"inputWrapWelcome\">\n    <div class=\"input-form\" data-sid=\"inputFormWelcome\">\n      \n      <textarea class=\"input-textarea\" data-sid=\"promptWelcome\" aria-label=\"Ask me...\" placeholder=\"Ask me...\" rows=\"1\" style=\"\"></textarea>\n      <div class=\"input-btns-right\">\n        <button class=\"attach-btn\" type=\"button\" data-sid=\"attachBtnWelcome\" title=\"Прикрепить документ\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48\"></path></svg></button>\n        <button class=\"mic-btn\" data-sid=\"micBtnWelcome\" aria-label=\"Голосовой ввод\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"></path><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"></path><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"></line><line x1=\"8\" y1=\"23\" x2=\"16\" y2=\"23\"></line></svg></button>\n        <button class=\"send-btn enabled\" data-sid=\"sendBtnWelcome\" aria-label=\"Отправить\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\"></line><polyline points=\"5 12 12 5 19 12\"></polyline></svg></button>\n      </div>\n    </div>\n    \n  </div>\n  <div class=\"upload-notice\" data-sid=\"uploadNoticeWelcome\">Do not upload documents containing personal data of third parties.<a class=\"upload-notice-link\" role=\"button\" tabindex=\"0\">Learn more</a></div>\n  <div class=\"disclaimer-text\"><a class=\"disclaimer-link\" role=\"button\" tabindex=\"0\">Moní can make mistakes</a></div>\n</div>", "attachChip": "<div class=\"attach-chip\" data-sid=\"moniAttachChip\"><span class=\"attach-ic\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline></svg></span><span class=\"attach-text\"><span class=\"attach-name\">Commercial_Lease_14-26.docx</span><span class=\"attach-sub\">Прикреплён · будет проанализирован при отправке</span></span><button class=\"attach-x\" type=\"button\" title=\"Убрать\">×</button></div>", "modeBarChat": "<div class=\"mode-bar compact\" data-sid=\"modeBarChat\">\n    <button class=\"mode-btn active\" data-mode=\"simple\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg></button>\n    <button class=\"mode-btn\" data-mode=\"calculate\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"4\" y=\"2\" width=\"16\" height=\"20\" rx=\"2\"></rect><line x1=\"8\" y1=\"6\" x2=\"16\" y2=\"6\"></line><line x1=\"8\" y1=\"10\" x2=\"10\" y2=\"10\"></line></svg></button>\n  </div>", "inputWrapChat": "<div class=\"input-wrap\" data-sid=\"inputWrapChat\">\n    <div class=\"input-form\" data-sid=\"inputFormChat\">\n      <textarea class=\"input-textarea\" data-sid=\"promptChat\" aria-label=\"Ask me...\" placeholder=\"Ask me...\" rows=\"1\" style=\"\"></textarea>\n      <div class=\"input-btns-right\">\n        <button class=\"attach-btn\" type=\"button\" data-sid=\"attachBtnChat\" title=\"Прикрепить документ\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48\"></path></svg></button>\n        <button class=\"mic-btn\" data-sid=\"micBtnChat\" aria-label=\"Голосовой ввод\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"></path><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"></path><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"></line></svg></button>\n        <button class=\"send-btn\" data-sid=\"sendBtnChat\" aria-label=\"Отправить\" disabled=\"\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\"></line><polyline points=\"5 12 12 5 19 12\"></polyline></svg></button>\n      </div>\n    </div>\n    <button class=\"clear-btn\" aria-label=\"Очистить чат\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"3 6 5 6 21 6\"></polyline><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"></path></svg></button>\n  </div>", "uploadNoticeChat": "<div class=\"upload-notice\" data-sid=\"uploadNoticeChat\">Do not upload documents containing personal data of third parties.<a class=\"upload-notice-link\" role=\"button\" tabindex=\"0\">Learn more</a></div>", "footerBottom": "<div class=\"footer-bottom\"><span class=\"disclaimer-link\" role=\"button\" tabindex=\"0\">Moní can make mistakes</span></div>", "qa": [{"cls": "msg msg-user", "route": "", "html": "<div class=\"msg-content\">Can an employer dismiss an employee during the probation period under the Labor Code of Tajikistan?</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}, {"cls": "msg msg-ai", "route": "SEARCH", "html": "<div class=\"msg-content\"><p><strong>Yes — but only on the ground and under the procedure set out in ТК РТ, ст. 28.</strong></p>\n<p><strong>1. The probation clause must exist in the contract</strong><br>Probation must be stipulated in the employment contract. If there is no such stipulation, the employee is deemed hired without preliminary probation (ТК РТ, ст. 28).</p>\n<p><strong>2. Dismissal on a negative result — the specific rule</strong><br>If the employee's work during probation produces a negative result, the employer has the right to terminate the employment contract, having warned the employee <strong>in writing not earlier than seven calendar days before the expiry of the probation period</strong>, stating the reasons that served as the basis for finding the employee to have failed probation (ТК РТ, ст. 28, п. 8).</p>\n<p>So the employer's right to dismiss during probation is conditional on three elements:</p>\n<ul>\n<li>a probation clause actually present in the contract;</li>\n<li>a negative result of the work;</li>\n<li>written notice given <strong>not earlier than 7 calendar days</strong> before the probation period ends, with reasons stated.</li>\n</ul>\n<p><strong>3. If no one acts by the end of probation</strong><br>If, upon expiry of the probation period, neither party has declared termination of the contract, the contract continues, and its subsequent termination is allowed on general grounds under the Code and other normative legal acts (ТК РТ, ст. 28, п. 7).</p>\n<p><strong>4. Promotion before probation ends</strong><br>If the employer appoints the employee to a higher position before the probation period expires, the employee is deemed to have passed probation (ТК РТ, ст. 28, п. 6).</p>\n<p><strong>5. Termination on grounds independent of the parties' will</strong><br>Separately, the contract is subject to termination on circumstances independent of the parties' will — including conscription or entry into military service, expiry of the term of authority, reinstatement of a previously dismissed employee who held the job, entry into force of a court sentence depriving the employee or the employer (a natural person) of liberty, a court decision declaring a person incapable or of limited capacity, death of the employee or of the employer (a natural person), declaration by court that they are dead or missing, violation of the established rules of hiring, and other cases provided by the legislation of the Republic of Tajikistan (ТК РТ, ст. 48).</p>\n<p><strong>6. Liability for unlawful dismissal</strong><br>Deliberately unlawful dismissal of a person from work, non-execution of a court decision on reinstatement, as well as other intentional substantial violation of the labour legislation of the Republic of Tajikistan is punishable by a fine of <strong>from one thousand to two thousand indicators for calculations</strong>, or imprisonment for <strong>up to three years</strong> (УК РТ, ст. 153, as amended by Законы РТ от 17.05.2004 г. № 35 and от 6.10.2008 г. № 422).</p>\n<p><strong>Summary</strong><br>Dismissal during probation is possible only where probation is agreed in the contract, the work result is negative, and written notice with reasons is given not earlier than 7 calendar days before the probation period expires (ТК РТ, ст. 28, п. 8). Absent those conditions, the contract continues and can be terminated only on general grounds (ТК РТ, ст. 28, п. 7).</p>\n<hr>\n<p><strong>Sources:</strong><br>• <strong>ТРУДОВОЙ КОДЕКС РЕСПУБЛИКИ ТАДЖИКИСТАН</strong> — ст. 50, 28, 48 (от 23.07.2016, ред. 17.06.2026)<br>• <strong>УГОЛОВНЫЙ КОДЕКС РЕСПУБЛИКИ ТАДЖИКИСТАН</strong> — ст. 153 (от 01.09.1998, ред. 20.06.2024)<br>• <strong>Закон РТ \"О содействии занятости населения\"</strong> — ст. 19 (от 01.08.2003, ред. 22.01.2026)</p>\n<p><em>Moní is not a substitute for personalized legal advice. For your specific situation, consult a qualified lawyer.</em></p>\n</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Like\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3\"></path></svg></button><button class=\"mbtn\" title=\"Dislike\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zm7-13h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17\"></path></svg></button><button class=\"mbtn\" title=\"Word\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"8\" y1=\"13\" x2=\"16\" y2=\"13\"></line><line x1=\"8\" y1=\"17\" x2=\"16\" y2=\"17\"></line><line x1=\"8\" y1=\"9\" x2=\"10\" y2=\"9\"></line></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}], "qa_limit": [{"cls": "msg msg-user", "route": "", "html": "<div class=\"msg-content\">What is the general limitation period (statute of limitations) under the Civil Code of the Republic of Tajikistan?</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}, {"cls": "msg msg-ai", "route": "SEARCH", "html": "<div class=\"msg-content\"><p><strong>Short answer:</strong> The provided sources do <strong>not</strong> state the general limitation period (its length in years) under the Civil Code of the Republic of Tajikistan. There is no article in the sources that fixes the general duration of the limitation period. What the sources do contain are rules on the <em>application</em>, <em>suspension</em>, and <em>scope</em> of limitation periods, plus specific periods in other acts.</p>\n<p><strong>What the sources actually establish on limitation periods</strong></p>\n<div class=\"tbl-wrap\"><div class=\"tbl-scroll\"><table data-moni-tbl=\"1\">\n<thead>\n<tr>\n<th>Rule</th>\n<th>Content</th>\n<th>Source</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Application of pre-2000 periods</td>\n<td>Limitation periods established by part one of the Civil Code of the Republic of Tajikistan apply to claims whose presentation periods under previously effective legislation had not expired before 1 January 2000</td>\n<td>ГК РТ, ст. 9</td>\n</tr>\n<tr>\n<td>Suspension of the running of the period</td>\n<td>The running of the limitation period is suspended in the listed cases (irresistible force; claimant or defendant in the Armed Forces transferred to martial law; a moratorium — deferral of performance of obligations established by the Government on the basis of law; suspension of the operation of a law or other legal act regulating the relevant relation; absence of a legal representative for an incapacitated person)</td>\n<td>ГК РТ, ст. 219, part 1</td>\n</tr>\n<tr>\n<td>Condition for suspension</td>\n<td>Suspension applies only if these circumstances arose or continued to exist in the <strong>last six months</strong> of the limitation period, and if that period is <strong>six months or less</strong> — during the whole period</td>\n<td>ГК РТ, ст. 219, part 2</td>\n</tr>\n<tr>\n<td>Out-of-court dispute procedure</td>\n<td>If the parties resort to a procedure for resolving the dispute out of court provided by law, the period is suspended for the term set by law for that procedure, and in the absence of such a term — for <strong>six months</strong> from the start of the procedure</td>\n<td>ГК РТ, ст. 219, part 3</td>\n</tr>\n<tr>\n<td>Resumption</td>\n<td>From the day the suspending circumstance ceases, the period continues; the remaining part is extended to <strong>six months</strong>, and if the period is six months or less — to the full period</td>\n<td>ГК РТ, ст. 219, part 4</td>\n</tr>\n<tr>\n<td>Family relations</td>\n<td>Limitation does not apply to claims arising from family relations, except where a period for protection of the violated right is set by the Family Code; courts are guided by the relevant norms of the Civil Code</td>\n<td>СК РТ, ст. 9</td>\n</tr>\n<tr>\n<td>Conflict-of-laws</td>\n<td>Limitation is determined by the law of the country applicable to the relevant relation; claims to which limitation does not apply are determined by the law of the Republic of Tajikistan if at least one participant is a citizen or legal entity of the Republic of Tajikistan</td>\n<td>ГК РТ, ст. 1327</td>\n</tr>\n</tbody></table></div><div class=\"tbl-tools\"><svg class=\"tbl-logo\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"currentColor\" opacity=\"0.14\"></circle><path d=\"M6 16V8l3.2 5L12.4 8v8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg><button type=\"button\" class=\"tbl-btn\" data-fmt=\"csv\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12\"></path><path d=\"m7 11 5 5 5-5\"></path><path d=\"M5 21h14\"></path></svg><span>CSV</span></button><button type=\"button\" class=\"tbl-btn\" data-fmt=\"xlsx\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12\"></path><path d=\"m7 11 5 5 5-5\"></path><path d=\"M5 21h14\"></path></svg><span>Excel</span></button><span class=\"tbl-status\" role=\"status\"></span></div></div>\n<p><strong>Specific periods in the sources (not the general one)</strong></p>\n<ul>\n<li>Claim to a carrier in domestic air carriage: <strong>6 months</strong>, counted as specified (from the day following delivery of cargo; for lost cargo — <strong>10 days</strong> after expiry of the delivery period; etc.); the carrier may accept a claim after expiry if it finds the reason valid (Воздушный кодекс РТ, ст. 107).</li>\n<li>Execution of an administrative act: <strong>1 month</strong> after adoption, extendable for valid reasons (КоАП-проц, ст. 78, part 1); deferral of execution — up to <strong>1 month</strong> (КоАП-проц, ст. 76).</li>\n<li>Appeal against an administrative act: <strong>1 month</strong> from entry into force; a missed period may be restored for a valid reason but cannot exceed <strong>1 year</strong> (КоАП-проц, ст. 94).</li>\n<li>Restoration of a missed procedural period: application within <strong>15 days</strong> after the obstacle is removed; the administrative body decides within <strong>5 days</strong> (КоАП-проц, ст. 44, parts 4–5).</li>\n<li>Citizenship requests: consideration cannot exceed <strong>1 year</strong> from submission of the request and all duly executed documents (Конституционный закон РТ о гражданстве, ст. 37).</li>\n</ul>\n<p><strong>Conclusion:</strong> the sources regulate how limitation periods are applied, suspended and resumed (ГК РТ, ст. 219), their application to pre-2000 claims (ГК РТ, ст. 9), their non-application in family matters (СК РТ, ст. 9) and their determination under conflict-of-laws rules (ГК РТ, ст. 1327), but they do <strong>not</strong> contain the general limitation period itself. There is no direct norm in the provided base stating its length.</p>\n<hr>\n<p><strong>Sources:</strong><br>• <strong>Закон РТ \"О принятии части первой Гражданского кодекса РТ\"</strong> — ст. 9 (от 30.06.1999, ред. 14.12.2018)<br>• <strong>КОНСТИТУЦИОННЫЙ ЗАКОН РЕСПУБЛИКИ ТАДЖИКИСТАН О ГРАЖДАНСТВЕ РЕСПУБЛИКИ ТАДЖИКИСТАН</strong> — ст. 37 (от 08.08.2015)<br>• <strong>Гражданский кодекс Республики Таджикистан</strong> — ст. 219, 1327 (от 01.07.2023, ред. 17.11.2024)<br>• <strong>СЕМЕЙНЫЙ КОДЕКС РЕСПУБЛИКИ ТАДЖИКИСТАН</strong> — ст. 9 (от 13.11.1998, ред. 03.01.2024)<br>• <strong>Кодекс об административных процедурах РТ</strong> — ст. 78, 44, 94, 75, 76 (от 05.03.2007, ред. 13.02.2013)</p>\n<p><em>Moní is not a substitute for personalized legal advice. For your specific situation, consult a qualified lawyer.</em></p>\n</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Like\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3\"></path></svg></button><button class=\"mbtn\" title=\"Dislike\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zm7-13h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17\"></path></svg></button><button class=\"mbtn\" title=\"Word\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"8\" y1=\"13\" x2=\"16\" y2=\"13\"></line><line x1=\"8\" y1=\"17\" x2=\"16\" y2=\"17\"></line><line x1=\"8\" y1=\"9\" x2=\"10\" y2=\"9\"></line></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}], "qa_consumer": [{"cls": "msg msg-user", "route": "", "html": "<div class=\"msg-content\">What rights does a consumer have after buying a defective product in Tajikistan?</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}, {"cls": "msg msg-ai", "route": "SEARCH", "html": "<div class=\"msg-content\"><p><strong>Rights of a consumer after buying a defective product (Закон РТ «О защите прав потребителей»)</strong></p>\n<p>If the seller did not stipulate the defect in advance, the consumer may, <strong>at their own choice</strong>, demand (Закон РТ «О защите прав потребителей», ст. 18):</p>\n<ul>\n<li>replacement with a product of the same brand (model, article) or a different brand (model, article) with a corresponding recalculation of the purchase price;</li>\n<li>free elimination of the defects, or reimbursement of the costs of eliminating them by the consumer or a third party;</li>\n<li>rescission of the sales contract;</li>\n<li>a proportionate reduction of the purchase price.</li>\n</ul>\n<p>The consumer may also demand <strong>full compensation of losses</strong> caused by the sale of a defective product (ст. 18).</p>\n<p><strong>Special rules depending on the type of product and defect</strong></p>\n<div class=\"tbl-wrap\"><div class=\"tbl-scroll\"><table data-moni-tbl=\"1\">\n<thead>\n<tr>\n<th>Situation</th>\n<th>Right of the consumer</th>\n<th>Norm</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Technically complex or expensive product</td>\n<td>Replacement may be demanded only if <strong>substantial defects</strong> (substantial violation of quality requirements) are found; the list of technically complex goods is approved by the Government of the Republic of Tajikistan</td>\n<td>Закон РТ «О защите прав потребителей», ст. 18</td>\n</tr>\n<tr>\n<td>Defect cannot be eliminated (by its nature)</td>\n<td>At the consumer's choice: replacement with a quality product, proportionate price reduction, or rescission of the contract</td>\n<td>Закон РТ «О защите прав потребителей», ст. 18</td>\n</tr>\n<tr>\n<td>Return of the defective product</td>\n<td>The consumer may return it to the seller (manufacturer) and demand refund of the amount paid; the seller (manufacturer) <strong>may not withhold</strong> from that sum any amount for loss of value due to full/partial use, loss of marketable appearance or similar circumstances</td>\n<td>Закон РТ «О защите прав потребителей», ст. 18 (в редакции Закона РТ от 29.01.2021г.№1769)</td>\n</tr>\n</tbody></table></div><div class=\"tbl-tools\"><svg class=\"tbl-logo\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"currentColor\" opacity=\"0.14\"></circle><path d=\"M6 16V8l3.2 5L12.4 8v8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg><button type=\"button\" class=\"tbl-btn\" data-fmt=\"csv\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12\"></path><path d=\"m7 11 5 5 5-5\"></path><path d=\"M5 21h14\"></path></svg><span>CSV</span></button><button type=\"button\" class=\"tbl-btn\" data-fmt=\"xlsx\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v12\"></path><path d=\"m7 11 5 5 5-5\"></path><path d=\"M5 21h14\"></path></svg><span>Excel</span></button><span class=\"tbl-status\" role=\"status\"></span></div></div>\n<p><strong>To whom the claim is addressed:</strong> the demands in part one of the article are made to the seller or to an organization performing the seller's functions under a sales contract with the consumer (Закон РТ «О защите прав потребителей», ст. 18).</p>\n<p><strong>How the money is calculated (Закон РТ «О защите прав потребителей», ст. 24)</strong></p>\n<ul>\n<li>Replacement with the same brand (model, article): <strong>no recalculation</strong> of price is made.</li>\n<li>Replacement with another brand (model, article): if the replaced product is cheaper than the replacement, the consumer <strong>pays the difference</strong>; if the replaced product is more expensive, the <strong>difference is paid to the consumer</strong>.</li>\n<li>Proportionate price reduction: the price is taken <strong>at the moment the consumer makes the claim</strong>, and if not voluntarily satisfied — <strong>at the moment the court renders the decision</strong>.</li>\n<li>Rescission of the contract: the consumer may demand refund of the amount paid <strong>plus</strong> the difference between the contract price and the price of the corresponding product at the moment of voluntary satisfaction, or, if not voluntarily satisfied, at the moment of the court decision.</li>\n<li>Goods sold <strong>on credit</strong>: on rescission, the consumer is refunded the amount paid <strong>in the amount of the credit repaid by the day of return</strong>, and the fee for granting the credit is also compensated.</li>\n</ul>\n<p><strong>General rights of the consumer (Закон РТ «О защите прав потребителей», ст. 3)</strong> include, among others: proper quality of goods (works, services); replacement or return of a defective product; elimination of defects and shortages; full compensation of losses (harm) caused by defects; and recourse to court or other state bodies to protect their rights and interests.</p>\n<p><strong>Related but distinct right — exchange of a good-quality product (Закон РТ «О защите прав потребителей», ст. 25):</strong> within <strong>fourteen calendar days</strong> from transfer of a non-food product (unless the seller announced a longer period), the consumer may exchange it for an analogous product of another size, form, dimensions, style, colour or configuration, with recalculation if prices differ. This requires that the product was <strong>not in use</strong>, its consumer properties are preserved, and there is <strong>evidence of purchase from that seller</strong>. The list of goods not subject to exchange is approved by the Government of the Republic of Tajikistan. If no analogous product is on sale on the day of the consumer's request, the consumer may return the product and receive the amount paid.</p>\n<p><strong>For services/works (Правила бытового обслуживания, п. 24):</strong> if defects in the service (work) are found, the consumer may at their choice demand free elimination of defects; a corresponding reduction of the price; free making of another item from homogeneous material of the same quality or re-performance of the work (returning the previously transferred item); or reimbursement of expenses incurred in eliminating defects by their own efforts or by a third party. The consumer may rescind the contract and demand full compensation of losses if the defects are not eliminated within the contract period, or if substantial defects or other substantial deviations from the contract terms are found.</p>\n<hr>\n<p><strong>Sources:</strong><br>• <strong>ЗАКОН РЕСПУБЛИКИ ТАДЖИКИСТАН О защите прав потребителей</strong> — ст. 18, 3, 25, 24 (от 09.12.2004, ред. 22.06.2023)<br>• <strong>Правила бытового обслуживания</strong> (от 06.06.2005, ред. 23.01.2025)</p>\n<p><em>Moní is not a substitute for personalized legal advice. For your specific situation, consult a qualified lawyer.</em></p>\n</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Like\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3\"></path></svg></button><button class=\"mbtn\" title=\"Dislike\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zm7-13h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17\"></path></svg></button><button class=\"mbtn\" title=\"Word\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"8\" y1=\"13\" x2=\"16\" y2=\"13\"></line><line x1=\"8\" y1=\"17\" x2=\"16\" y2=\"17\"></line><line x1=\"8\" y1=\"9\" x2=\"10\" y2=\"9\"></line></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}], "draft": [{"cls": "msg msg-user", "route": "", "html": "<div class=\"msg-content\">Draft a services agreement in English for the development of a new corporate website (6 pages: home, about, services, news, contacts, admin CMS) between Pamir Trade LLC (Client) and Somon Digital LLC (Contractor), Dushanbe. Fee TJS 25,000; term 60 calendar days; 50% advance, 50% within 5 days after signing the acceptance certificate. Stages: design mockup, development, testing, launch. Hosting and domain are provided by the Client. All IP rights pass to the Client upon full payment. 3-month warranty for bug fixes. Governing law: Republic of Tajikistan. Please draft the full agreement now.</div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}, {"cls": "msg msg-ai", "route": "DRAFT", "html": "<div class=\"msg-content\"><p>Составил проект договора (иной). Проверьте и заполните пометки «[уточнить: …]».</p><div class=\"doc-card\" role=\"button\" tabindex=\"0\"><span class=\"doc-card-ic\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"8\" y1=\"13\" x2=\"16\" y2=\"13\"></line><line x1=\"8\" y1=\"17\" x2=\"13\" y2=\"17\"></line></svg></span><span class=\"doc-card-info\"><span class=\"doc-card-name\">Договор об оказании услуг № [уточнить: номер договора]</span><span class=\"doc-card-meta\">Документ · нажмите, чтобы открыть</span></span><button type=\"button\" class=\"doc-card-dl\" title=\"Скачать Word\" aria-label=\"Скачать Word\"><svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"7 10 12 15 17 10\"></polyline><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line></svg></button></div><p class=\"doc-card-disc\">Moní is not a substitute for personalized legal advice. For your specific situation, consult a qualified lawyer.</p></div><div class=\"msg-btns\"><button class=\"mbtn\" title=\"Copy\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"></rect><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"></path></svg></button><button class=\"mbtn\" title=\"Like\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3\"></path></svg></button><button class=\"mbtn\" title=\"Dislike\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zm7-13h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17\"></path></svg></button><button class=\"mbtn\" title=\"Word\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"8\" y1=\"13\" x2=\"16\" y2=\"13\"></line><line x1=\"8\" y1=\"17\" x2=\"16\" y2=\"17\"></line><line x1=\"8\" y1=\"9\" x2=\"10\" y2=\"9\"></line></svg></button><button class=\"mbtn\" title=\"Share\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"></line><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"></line></svg></button></div>"}], "docViewer": "<div class=\"dv-panel\" role=\"dialog\" aria-label=\"Просмотр документа\"><div class=\"dv-header\"><div class=\"dv-title\">Договор об оказании услуг № [уточнить: номер договора]</div><button type=\"button\" class=\"dv-close\" aria-label=\"Закрыть\">×</button></div><div class=\"dv-findings\" hidden=\"\"></div><div class=\"dv-body\"><div class=\"dv-sheet\"><p class=\"dv-para dv-p-title\">ДОГОВОР ОБ ОКАЗАНИИ УСЛУГ № [уточнить: номер договора]</p><p class=\"dv-para\">г. Душанбе                                                                   «[уточнить: день]» [уточнить: месяц] 20[уточнить: год] г.</p><p class=\"dv-para\">Общество с ограниченной ответственностью «Памир Трейд», зарегистрированное в соответствии с законодательством Республики Таджикистан, ИНН [уточнить: ИНН], свидетельство о государственной регистрации № [уточнить: номер свидетельства], юридический адрес: [уточнить: адрес], в лице [уточнить: должность, Ф.И.О. руководителя или представителя], действующего на основании [уточнить: Устава / доверенности № ___ от ___], именуемое в дальнейшем «Заказчик», с одной стороны, и</p><p class=\"dv-para\">Общество с ограниченной ответственностью «Сомон Диджитал», зарегистрированное в соответствии с законодательством Республики Таджикистан, ИНН [уточнить: ИНН], свидетельство о государственной регистрации № [уточнить: номер свидетельства], юридический адрес: г. Душанбе, [уточнить: адрес], в лице [уточнить: должность, Ф.И.О. руководителя или представителя], действующего на основании [уточнить: Устава / доверенности № ___ от ___], именуемое в дальнейшем «Исполнитель», с другой стороны,</p><p class=\"dv-para\">в отдельности именуемые «Сторона», а совместно — «Стороны», заключили настоящий Договор о нижеследующем.</p><p class=\"dv-para dv-p-head\">1. ПРЕДМЕТ ДОГОВОРА</p><p class=\"dv-para\">1.1. Исполнитель обязуется по заданию Заказчика оказать услуги по разработке нового корпоративного веб-сайта Заказчика (далее — «Сайт»), а Заказчик обязуется принять и оплатить оказанные услуги в порядке и на условиях, предусмотренных настоящим Договором.</p><p class=\"dv-para\">1.2. Сайт включает следующие страницы и функциональные элементы (объём услуг):\n1.2.1. главная страница;\n1.2.2. страница «О компании»;\n1.2.3. страница «Услуги»;\n1.2.4. страница «Новости»;\n1.2.5. страница «Контакты»;\n1.2.6. административная панель управления контентом (CMS), обеспечивающая создание, редактирование, удаление и публикацию материалов указанных страниц, а также управление разделами новостей.</p><p class=\"dv-para\">1.3. Услуги оказываются в следующие этапы (стадии):\n1.3.1. Этап 1 — разработка дизайн-макета Сайта (дизайн-концепция и макеты всех страниц, указанных в пункте 1.2);\n1.3.2. Этап 2 — разработка Сайта (вёрстка, программирование, интеграция CMS);\n1.3.3. Этап 3 — тестирование Сайта (функциональное тестирование, проверка отображения, устранение выявленных недостатков);\n1.3.4. Этап 4 — запуск Сайта (размещение на хостинге Заказчика, публикация, передача доступов).</p></div><div class=\"dv-sheet\"><p class=\"dv-para\">1.4. Хостинг и доменное имя для размещения Сайта предоставляются Заказчиком. Исполнитель не несёт ответственности за работу хостинг-провайдера и регистратора доменных имён, а также за перебои, возникшие по причинам, зависящим от них.</p><p class=\"dv-para\">1.5. Результатом оказанных услуг является функционирующий Сайт, размещённый на хостинге Заказчика, а также исходные материалы (дизайн-макеты, исходный код, файлы Сайта), передаваемые Заказчику в порядке, установленном настоящим Договором.</p><p class=\"dv-para dv-p-head\">2. СРОКИ ОКАЗАНИЯ УСЛУГ</p><p class=\"dv-para\">2.1. Общий срок оказания услуг по настоящему Договору составляет 60 (шестьдесят) календарных дней с даты начала оказания услуг.</p><p class=\"dv-para\">2.2. Датой начала оказания услуг является дата поступления авансового платежа, предусмотренного пунктом 3.3.1 настоящего Договора, на расчётный счёт Исполнителя.</p><p class=\"dv-para\">2.3. Сроки по этапам:\n2.3.1. Этап 1 (дизайн-макет) — в течение 15 (пятнадцати) календарных дней с даты начала оказания услуг;\n2.3.2. Этап 2 (разработка) — в течение 30 (тридцати) календарных дней с даты завершения Этапа 1;\n2.3.3. Этап 3 (тестирование) — в течение 10 (десяти) календарных дней с даты завершения Этапа 2;\n2.3.4. Этап 4 (запуск) — в течение 5 (пяти) календарных дней с даты завершения Этапа 3.</p><p class=\"dv-para\">2.4. Срок оказания услуг продлевается на период просрочки исполнения Заказчиком своих встречных обязательств (предоставление материалов, согласований, доступов, хостинга и доменного имени), если такая просрочка препятствует оказанию услуг.</p><p class=\"dv-para dv-p-head\">3. ЦЕНА ДОГОВОРА И ПОРЯДОК РАСЧЁТОВ</p><p class=\"dv-para\">3.1. Общая стоимость услуг по настоящему Договору составляет 25 000 (двадцать пять тысяч) сомони (TJS), без налога на добавленную стоимость [уточнить: при необходимости — с НДС, указать ставку и сумму].</p><p class=\"dv-para\">3.2. Валюта расчётов между Сторонами — сомони (TJS). Все платежи осуществляются в безналичном порядке путём перечисления денежных средств на расчётный счёт Исполнителя.</p><p class=\"dv-para\">3.3. Порядок оплаты:\n3.3.1. авансовый платёж в размере 50% от общей стоимости услуг, что составляет 12 500 (двенадцать тысяч пятьсот) сомони, уплачивается Заказчиком в течение 5 (пяти) рабочих дней с даты подписания настоящего Договора;\n3.3.2. окончательный платёж в размере 50% от общей стоимости услуг, что составляет 12 500 (двенадцать тысяч пятьсот) сомони, уплачивается Заказчиком в течение 5 (пяти) рабочих дней с даты подписания Акта приёмки оказанных услуг.</p><p class=\"dv-para\">3.4. Датой оплаты считается дата зачисления денежных средств на расчётный счёт Исполнителя.</p><p class=\"dv-para\">3.5. Стоимость услуг является фиксированной на весь срок действия настоящего Договора, за исключением случаев изменения объёма услуг по соглашению Сторон, оформленному в письменной форме.</p></div><div class=\"dv-sheet\"><p class=\"dv-para dv-p-head\">4. ПРАВА И ОБЯЗАННОСТИ СТОРОН</p><p class=\"dv-para\">4.1. Исполнитель обязуется:\n4.1.1. оказать услуги в объёме и в сроки, предусмотренные настоящим Договором, качественно и в соответствии с условиями настоящего Договора;\n4.1.2. выполнить работы по всем этапам, указанным в пункте 1.3 настоящего Договора;\n4.1.3. предоставить Заказчику дизайн-макет Сайта на согласование по завершении Этапа 1;\n4.1.4. обеспечить интеграцию административной панели управления контентом (CMS) в объёме, предусмотренном пунктом 1.2.6 настоящего Договора;\n4.1.5. провести тестирование Сайта и устранить выявленные недостатки до запуска;\n4.1.6. разместить Сайт на хостинге, предоставленном Заказчиком, и передать Заказчику доступы к Сайту и CMS;\n4.1.7. передать Заказчику исходные материалы (дизайн-макеты, исходный код, файлы Сайта) в порядке, установленном разделом 6 настоящего Договора;\n4.1.8. в течение гарантийного срока, установленного разделом 7 настоящего Договора, безвозмездно устранять ошибки и недостатки Сайта, возникшие по вине Исполнителя;\n4.1.9. своевременно информировать Заказчика о ходе оказания услуг и о возникновении обстоятельств, препятствующих их оказанию.</p><p class=\"dv-para\">4.2. Исполнитель вправе:\n4.2.1. запрашивать у Заказчика материалы, сведения и доступы, необходимые для оказания услуг;\n4.2.2. привлекать третьих лиц для оказания услуг с предварительного письменного согласия Заказчика, оставаясь ответственным перед Заказчиком за результат их действий.</p><p class=\"dv-para\">4.3. Заказчик обязуется:\n4.3.1. предоставить Исполнителю материалы, сведения и доступы, необходимые для оказания услуг, в том числе доступ к хостингу и доменному имени;\n4.3.2. рассматривать и согласовывать представленные Исполнителем материалы (дизайн-макет, результаты этапов) в срок не более 5 (пяти) рабочих дней с даты их получения;\n4.3.3. принять оказанные услуги и подписать Акт приёмки оказанных услуг либо представить мотивированный отказ в порядке, установленном разделом 5 настоящего Договора;\n4.3.4. оплатить услуги в размере и в сроки, предусмотренные разделом 3 настоящего Договора.</p><p class=\"dv-para\">4.4. Заказчик вправе:\n4.4.1. контролировать ход и качество оказания услуг;\n4.4.2. требовать устранения недостатков, выявленных при приёмке услуг и в течение гарантийного срока.</p><p class=\"dv-para dv-p-head\">5. ПОРЯДОК СДАЧИ-ПРИЁМКИ УСЛУГ</p><p class=\"dv-para\">5.1. По завершении каждого этапа Исполнитель представляет Заказчику результаты этапа и уведомляет о готовности к приёмке.</p><p class=\"dv-para\">5.2. По завершении всех этапов Исполнитель представляет Заказчику Акт приёмки оказанных услуг.</p></div><div class=\"dv-sheet\"><p class=\"dv-para\">5.3. Заказчик в течение 5 (пяти) рабочих дней с даты получения Акта приёмки оказанных услуг обязан подписать его либо представить Исполнителю письменный мотивированный отказ с перечнем выявленных недостатков.</p><p class=\"dv-para\">5.4. При наличии мотивированного отказа Стороны составляют перечень недостатков, подлежащих устранению. Исполнитель устраняет недостатки в срок не более 10 (десяти) рабочих дней с даты получения мотивированного отказа и повторно представляет Акт приёмки оказанных услуг.</p><p class=\"dv-para\">5.5. Если Заказчик в срок, установленный пунктом 5.3 настоящего Договора, не подписал Акт приёмки оказанных услуг и не представил мотивированный отказ, услуги считаются принятыми, а Акт приёмки оказанных услуг — подписанным.</p><p class=\"dv-para dv-p-head\">6. ИНТЕЛЛЕКТУАЛЬНАЯ СОБСТВЕННОСТЬ</p><p class=\"dv-para\">6.1. Исключительные права на результаты услуг, включая дизайн-макеты, исходный код, файлы Сайта и иные материалы, созданные Исполнителем в рамках настоящего Договора, переходят к Заказчику в полном объёме с момента полной оплаты услуг в соответствии с пунктом 3.3.2 настоящего Договора.</p><p class=\"dv-para\">6.2. До момента полной оплаты услуг исключительные права на результаты услуг сохраняются за Исполнителем. Заказчик вправе использовать результаты услуг в объёме, необходимом для их приёмки и тестирования.</p><p class=\"dv-para\">6.3. Исполнитель гарантирует, что результаты услуг не нарушают прав интеллектуальной собственности третьих лиц. При предъявлении третьими лицами соответствующих претензий Исполнитель принимает меры к урегулированию таких претензий.</p><p class=\"dv-para dv-p-head\">7. ГАРАНТИЙНЫЕ ОБЯЗАТЕЛЬСТВА</p><p class=\"dv-para\">7.1. Исполнитель предоставляет гарантию на Сайт сроком 3 (три) месяца с даты подписания Акта приёмки оказанных услуг.</p><p class=\"dv-para\">7.2. В течение гарантийного срока Исполнитель безвозмездно устраняет ошибки и недостатки Сайта, возникшие по вине Исполнителя, в срок не более 10 (десяти) рабочих дней с даты получения соответствующего уведомления Заказчика.</p><p class=\"dv-para\">7.3. Гарантия не распространяется на недостатки, возникшие вследствие: изменения Сайта третьими лицами или Заказчиком без участия Исполнителя; нарушения Заказчиком условий эксплуатации; сбоев хостинга, доменного имени или иных сервисов, предоставляемых Заказчиком или третьими лицами.</p><p class=\"dv-para dv-p-head\">8. ОТВЕТСТВЕННОСТЬ СТОРОН</p><p class=\"dv-para\">8.1. За нарушение сроков оказания услуг Исполнитель уплачивает Заказчику пеню в размере 0,1% от стоимости неоказанных в срок услуг за каждый день просрочки, но не более 10% от общей стоимости услуг по настоящему Договору.</p><p class=\"dv-para\">8.2. За нарушение сроков оплаты Заказчик уплачивает Исполнителю пеню в размере 0,1% от просроченной суммы за каждый день просрочки, но не более 10% от просроченной суммы.</p></div><div class=\"dv-sheet\"><p class=\"dv-para\">8.3. Уплата пени не освобождает Стороны от исполнения обязательств в натуре.</p><p class=\"dv-para\">8.4. Стороны несут ответственность в соответствии с законодательством Республики Таджикистан.</p><p class=\"dv-para dv-p-head\">9. ОБСТОЯТЕЛЬСТВА НЕПРЕОДОЛИМОЙ СИЛЫ (ФОРС-МАЖОР)</p><p class=\"dv-para\">9.1. Стороны освобождаются от ответственности за неисполнение или ненадлежащее исполнение обязательств по настоящему Договору, если оно вызвано обстоятельствами непреодолимой силы: стихийными бедствиями, военными действиями, актами органов государственной власти, иными обстоятельствами, которые Стороны не могли предвидеть и предотвратить.</p><p class=\"dv-para\">9.2. Сторона, для которой возникли обстоятельства непреодолимой силы, обязана уведомить другую Сторону в письменной форме в течение 5 (пяти) рабочих дней с даты их возникновения.</p><p class=\"dv-para\">9.3. Если обстоятельства непреодолимой силы продолжаются более 30 (тридцати) календарных дней, каждая из Сторон вправе расторгнуть настоящий Договор, направив письменное уведомление другой Стороне.</p><p class=\"dv-para dv-p-head\">10. ПОРЯДОК РАСТОРЖЕНИЯ ДОГОВОРА</p><p class=\"dv-para\">10.1. Настоящий Договор может быть расторгнут по соглашению Сторон, а также в одностороннем порядке в случаях, предусмотренных настоящим Договором и законодательством Республики Таджикистан.</p><p class=\"dv-para\">10.2. Каждая из Сторон вправе расторгнуть настоящий Договор в одностороннем порядке, направив другой Стороне письменное уведомление не менее чем за 15 (пятнадцать) календарных дней до предполагаемой даты расторжения.</p><p class=\"dv-para\">10.3. При расторжении настоящего Договора Стороны производят взаиморасчёты за фактически оказанные услуги на дату расторжения.</p><p class=\"dv-para dv-p-head\">11. РАЗРЕШЕНИЕ СПОРОВ И ПРИМЕНИМОЕ ПРАВО</p><p class=\"dv-para\">11.1. Настоящий Договор регулируется и толкуется в соответствии с законодательством Республики Таджикистан.</p><p class=\"dv-para\">11.2. Все споры и разногласия, возникающие из настоящего Договора или в связи с ним, разрешаются путём переговоров. Стороны устанавливают претензионный порядок: срок рассмотрения претензии составляет 10 (десять) рабочих дней с даты её получения.</p><p class=\"dv-para\">11.3. При недостижении согласия спор передаётся на рассмотрение экономического суда Республики Таджикистан по месту нахождения ответчика.</p><p class=\"dv-para dv-p-head\">12. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ</p><p class=\"dv-para\">12.1. Настоящий Договор вступает в силу с даты подписания и действует до полного исполнения Сторонами своих обязательств.</p><p class=\"dv-para\">12.2. Все изменения и дополнения к настоящему Договору оформляются в письменной форме и подписываются уполномоченными представителями Сторон.</p><p class=\"dv-para\">12.3. Настоящий Договор составлен в двух экземплярах, имеющих равную юридическую силу, по одному для каждой из Сторон.</p><p class=\"dv-para dv-p-head\">13. РЕКВИЗИТЫ И ПОДПИСИ СТОРОН</p></div><div class=\"dv-sheet\"><p class=\"dv-para\">Заказчик:\nООО «Памир Трейд»\nИНН: [уточнить: ИНН]\nСвидетельство о государственной регистрации №: [уточнить: номер свидетельства]\nЮридический адрес: [уточнить: адрес]\nРасчётный счёт: [уточнить: номер счёта]\nБанк: [уточнить: наименование банка]\nБИК: [уточнить: БИК]\nТелефон: [уточнить: телефон]\nЭлектронная почта: [уточнить: адрес электронной почты]</p><p class=\"dv-para\">Руководитель / представитель: _________________________ / [уточнить: Ф.И.О.] /\nМ.П.</p><p class=\"dv-para\">Исполнитель:\nООО «Сомон Диджитал»\nИНН: [уточнить: ИНН]\nСвидетельство о государственной регистрации №: [уточнить: номер свидетельства]\nЮридический адрес: г. Душанбе, [уточнить: адрес]\nРасчётный счёт: [уточнить: номер счёта]\nБанк: [уточнить: наименование банка]\nБИК: [уточнить: БИК]\nТелефон: [уточнить: телефон]\nЭлектронная почта: [уточнить: адрес электронной почты]</p><p class=\"dv-para\">Руководитель / представитель: _________________________ / [уточнить: Ф.И.О.] /\nМ.П.</p></div></div><div class=\"dv-comments\"><div class=\"dv-comments-title\">Ваши комментарии (<span class=\"dv-cc\">0</span>)</div><div class=\"dv-comments-list\"></div><button type=\"button\" class=\"dv-send-btn\" hidden=\"\">Отправить замечания в чат</button></div></div>", "draftDoc": {"title": "Договор об оказании услуг № [уточнить: номер договора]", "text": "ДОГОВОР ОБ ОКАЗАНИИ УСЛУГ № [уточнить: номер договора]\n\nг. Душанбе                                                                   «[уточнить: день]» [уточнить: месяц] 20[уточнить: год] г.\n\nОбщество с ограниченной ответственностью «Памир Трейд», зарегистрированное в соответствии с законодательством Республики Таджикистан, ИНН [уточнить: ИНН], свидетельство о государственной регистрации № [уточнить: номер свидетельства], юридический адрес: [уточнить: адрес], в лице [уточнить: должность, Ф.И.О. руководителя или представителя], действующего на основании [уточнить: Устава / доверенности № ___ от ___], именуемое в дальнейшем «Заказчик», с одной стороны, и\n\nОбщество с ограниченной ответственностью «Сомон Диджитал», зарегистрированное в соответствии с законодательством Республики Таджикистан, ИНН [уточнить: ИНН], свидетельство о государственной регистрации № [уточнить: номер свидетельства], юридический адрес: г. Душанбе, [уточнить: адрес], в лице [уточнить: должность, Ф.И.О. руководителя или представителя], действующего на основании [уточнить: Устава / доверенности № ___ от ___], именуемое в дальнейшем «Исполнитель», с другой стороны,\n\nв отдельности именуемые «Сторона», а совместно — «Стороны», заключили настоящий Договор о нижеследующем.\n\n1. ПРЕДМЕТ ДОГОВОРА\n\n1.1. Исполнитель обязуется по заданию Заказчика оказать услуги по разработке нового корпоративного веб-сайта Заказчика (далее — «Сайт»), а Заказчик обязуется принять и оплатить оказанные услуги в порядке и на условиях, предусмотренных настоящим Договором.\n\n1.2. Сайт включает следующие страницы и функциональные элементы (объём услуг):\n1.2.1. главная страница;\n1.2.2. страница «О компании»;\n1.2.3. страница «Услуги»;\n1.2.4. страница «Новости»;\n1.2.5. страница «Контакты»;\n1.2.6. административная панель управления контентом (CMS), обеспечивающая создание, редактирование, удаление и публикацию материалов указанных страниц, а также управление разделами новостей.\n\n1.3. Услуги оказываются в следующие этапы (стадии):\n1.3.1. Этап 1 — разработка дизайн-макета Сайта (дизайн-концепция и макеты всех страниц, указанных в пункте 1.2);\n1.3.2. Этап 2 — разработка Сайта (вёрстка, программирование, интеграция CMS);\n1.3.3. Этап 3 — тестирование Сайта (функциональное тестирование, проверка отображения, устранение выявленных недостатков);\n1.3.4. Этап 4 — запуск Сайта (размещение на хостинге Заказчика, публикация, передача доступов).\n\n1.4. Хостинг и доменное имя для размещения Сайта предоставляются Заказчиком. Исполнитель не несёт ответственности за работу хостинг-провайдера и регистратора доменных имён, а также за перебои, возникшие по причинам, зависящим от них.\n\n1.5. Результатом оказанных услуг является функционирующий Сайт, размещённый на хостинге Заказчика, а также исходные материалы (дизайн-макеты, исходный код, файлы Сайта), передаваемые Заказчику в порядке, установленном настоящим Договором.\n\n2. СРОКИ ОКАЗАНИЯ УСЛУГ\n\n2.1. Общий срок оказания услуг по настоящему Договору составляет 60 (шестьдесят) календарных дней с даты начала оказания услуг.\n\n2.2. Датой начала оказания услуг является дата поступления авансового платежа, предусмотренного пунктом 3.3.1 настоящего Договора, на расчётный счёт Исполнителя.\n\n2.3. Сроки по этапам:\n2.3.1. Этап 1 (дизайн-макет) — в течение 15 (пятнадцати) календарных дней с даты начала оказания услуг;\n2.3.2. Этап 2 (разработка) — в течение 30 (тридцати) календарных дней с даты завершения Этапа 1;\n2.3.3. Этап 3 (тестирование) — в течение 10 (десяти) календарных дней с даты завершения Этапа 2;\n2.3.4. Этап 4 (запуск) — в течение 5 (пяти) календарных дней с даты завершения Этапа 3.\n\n2.4. Срок оказания услуг продлевается на период просрочки исполнения Заказчиком своих встречных обязательств (предоставление материалов, согласований, доступов, хостинга и доменного имени), если такая просрочка препятствует оказанию услуг.\n\n3. ЦЕНА ДОГОВОРА И ПОРЯДОК РАСЧЁТОВ\n\n3.1. Общая стоимость услуг по настоящему Договору составляет 25 000 (двадцать пять тысяч) сомони (TJS), без налога на добавленную стоимость [уточнить: при необходимости — с НДС, указать ставку и сумму].\n\n3.2. Валюта расчётов между Сторонами — сомони (TJS). Все платежи осуществляются в безналичном порядке путём перечисления денежных средств на расчётный счёт Исполнителя.\n\n3.3. Порядок оплаты:\n3.3.1. авансовый платёж в размере 50% от общей стоимости услуг, что составляет 12 500 (двенадцать тысяч пятьсот) сомони, уплачивается Заказчиком в течение 5 (пяти) рабочих дней с даты подписания настоящего Договора;\n3.3.2. окончательный платёж в размере 50% от общей стоимости услуг, что составляет 12 500 (двенадцать тысяч пятьсот) сомони, уплачивается Заказчиком в течение 5 (пяти) рабочих дней с даты подписания Акта приёмки оказанных услуг.\n\n3.4. Датой оплаты считается дата зачисления денежных средств на расчётный счёт Исполнителя.\n\n3.5. Стоимость услуг является фиксированной на весь срок действия настоящего Договора, за исключением случаев изменения объёма услуг по соглашению Сторон, оформленному в письменной форме.\n\n4. ПРАВА И ОБЯЗАННОСТИ СТОРОН\n\n4.1. Исполнитель обязуется:\n4.1.1. оказать услуги в объёме и в сроки, предусмотренные настоящим Договором, качественно и в соответствии с условиями настоящего Договора;\n4.1.2. выполнить работы по всем этапам, указанным в пункте 1.3 настоящего Договора;\n4.1.3. предоставить Заказчику дизайн-макет Сайта на согласование по завершении Этапа 1;\n4.1.4. обеспечить интеграцию административной панели управления контентом (CMS) в объёме, предусмотренном пунктом 1.2.6 настоящего Договора;\n4.1.5. провести тестирование Сайта и устранить выявленные недостатки до запуска;\n4.1.6. разместить Сайт на хостинге, предоставленном Заказчиком, и передать Заказчику доступы к Сайту и CMS;\n4.1.7. передать Заказчику исходные материалы (дизайн-макеты, исходный код, файлы Сайта) в порядке, установленном разделом 6 настоящего Договора;\n4.1.8. в течение гарантийного срока, установленного разделом 7 настоящего Договора, безвозмездно устранять ошибки и недостатки Сайта, возникшие по вине Исполнителя;\n4.1.9. своевременно информировать Заказчика о ходе оказания услуг и о возникновении обстоятельств, препятствующих их оказанию.\n\n4.2. Исполнитель вправе:\n4.2.1. запрашивать у Заказчика материалы, сведения и доступы, необходимые для оказания услуг;\n4.2.2. привлекать третьих лиц для оказания услуг с предварительного письменного согласия Заказчика, оставаясь ответственным перед Заказчиком за результат их действий.\n\n4.3. Заказчик обязуется:\n4.3.1. предоставить Исполнителю материалы, сведения и доступы, необходимые для оказания услуг, в том числе доступ к хостингу и доменному имени;\n4.3.2. рассматривать и согласовывать представленные Исполнителем материалы (дизайн-макет, результаты этапов) в срок не более 5 (пяти) рабочих дней с даты их получения;\n4.3.3. принять оказанные услуги и подписать Акт приёмки оказанных услуг либо представить мотивированный отказ в порядке, установленном разделом 5 настоящего Договора;\n4.3.4. оплатить услуги в размере и в сроки, предусмотренные разделом 3 настоящего Договора.\n\n4.4. Заказчик вправе:\n4.4.1. контролировать ход и качество оказания услуг;\n4.4.2. требовать устранения недостатков, выявленных при приёмке услуг и в течение гарантийного срока.\n\n5. ПОРЯДОК СДАЧИ-ПРИЁМКИ УСЛУГ\n\n5.1. По завершении каждого этапа Исполнитель представляет Заказчику результаты этапа и уведомляет о готовности к приёмке.\n\n5.2. По завершении всех этапов Исполнитель представляет Заказчику Акт приёмки оказанных услуг.\n\n5.3. Заказчик в течение 5 (пяти) рабочих дней с даты получения Акта приёмки оказанных услуг обязан подписать его либо представить Исполнителю письменный мотивированный отказ с перечнем выявленных недостатков.\n\n5.4. При наличии мотивированного отказа Стороны составляют перечень недостатков, подлежащих устранению. Исполнитель устраняет недостатки в срок не более 10 (десяти) рабочих дней с даты получения мотивированного отказа и повторно представляет Акт приёмки оказанных услуг.\n\n5.5. Если Заказчик в срок, установленный пунктом 5.3 настоящего Договора, не подписал Акт приёмки оказанных услуг и не представил мотивированный отказ, услуги считаются принятыми, а Акт приёмки оказанных услуг — подписанным.\n\n6. ИНТЕЛЛЕКТУАЛЬНАЯ СОБСТВЕННОСТЬ\n\n6.1. Исключительные права на результаты услуг, включая дизайн-макеты, исходный код, файлы Сайта и иные материалы, созданные Исполнителем в рамках настоящего Договора, переходят к Заказчику в полном объёме с момента полной оплаты услуг в соответствии с пунктом 3.3.2 настоящего Договора.\n\n6.2. До момента полной оплаты услуг исключительные права на результаты услуг сохраняются за Исполнителем. Заказчик вправе использовать результаты услуг в объёме, необходимом для их приёмки и тестирования.\n\n6.3. Исполнитель гарантирует, что результаты услуг не нарушают прав интеллектуальной собственности третьих лиц. При предъявлении третьими лицами соответствующих претензий Исполнитель принимает меры к урегулированию таких претензий.\n\n7. ГАРАНТИЙНЫЕ ОБЯЗАТЕЛЬСТВА\n\n7.1. Исполнитель предоставляет гарантию на Сайт сроком 3 (три) месяца с даты подписания Акта приёмки оказанных услуг.\n\n7.2. В течение гарантийного срока Исполнитель безвозмездно устраняет ошибки и недостатки Сайта, возникшие по вине Исполнителя, в срок не более 10 (десяти) рабочих дней с даты получения соответствующего уведомления Заказчика.\n\n7.3. Гарантия не распространяется на недостатки, возникшие вследствие: изменения Сайта третьими лицами или Заказчиком без участия Исполнителя; нарушения Заказчиком условий эксплуатации; сбоев хостинга, доменного имени или иных сервисов, предоставляемых Заказчиком или третьими лицами.\n\n8. ОТВЕТСТВЕННОСТЬ СТОРОН\n\n8.1. За нарушение сроков оказания услуг Исполнитель уплачивает Заказчику пеню в размере 0,1% от стоимости неоказанных в срок услуг за каждый день просрочки, но не более 10% от общей стоимости услуг по настоящему Договору.\n\n8.2. За нарушение сроков оплаты Заказчик уплачивает Исполнителю пеню в размере 0,1% от просроченной суммы за каждый день просрочки, но не более 10% от просроченной суммы.\n\n8.3. Уплата пени не освобождает Стороны от исполнения обязательств в натуре.\n\n8.4. Стороны несут ответственность в соответствии с законодательством Республики Таджикистан.\n\n9. ОБСТОЯТЕЛЬСТВА НЕПРЕОДОЛИМОЙ СИЛЫ (ФОРС-МАЖОР)\n\n9.1. Стороны освобождаются от ответственности за неисполнение или ненадлежащее исполнение обязательств по настоящему Договору, если оно вызвано обстоятельствами непреодолимой силы: стихийными бедствиями, военными действиями, актами органов государственной власти, иными обстоятельствами, которые Стороны не могли предвидеть и предотвратить.\n\n9.2. Сторона, для которой возникли обстоятельства непреодолимой силы, обязана уведомить другую Сторону в письменной форме в течение 5 (пяти) рабочих дней с даты их возникновения.\n\n9.3. Если обстоятельства непреодолимой силы продолжаются более 30 (тридцати) календарных дней, каждая из Сторон вправе расторгнуть настоящий Договор, направив письменное уведомление другой Стороне.\n\n10. ПОРЯДОК РАСТОРЖЕНИЯ ДОГОВОРА\n\n10.1. Настоящий Договор может быть расторгнут по соглашению Сторон, а также в одностороннем порядке в случаях, предусмотренных настоящим Договором и законодательством Республики Таджикистан.\n\n10.2. Каждая из Сторон вправе расторгнуть настоящий Договор в одностороннем порядке, направив другой Стороне письменное уведомление не менее чем за 15 (пятнадцать) календарных дней до предполагаемой даты расторжения.\n\n10.3. При расторжении настоящего Договора Стороны производят взаиморасчёты за фактически оказанные услуги на дату расторжения.\n\n11. РАЗРЕШЕНИЕ СПОРОВ И ПРИМЕНИМОЕ ПРАВО\n\n11.1. Настоящий Договор регулируется и толкуется в соответствии с законодательством Республики Таджикистан.\n\n11.2. Все споры и разногласия, возникающие из настоящего Договора или в связи с ним, разрешаются путём переговоров. Стороны устанавливают претензионный порядок: срок рассмотрения претензии составляет 10 (десять) рабочих дней с даты её получения.\n\n11.3. При недостижении согласия спор передаётся на рассмотрение экономического суда Республики Таджикистан по месту нахождения ответчика.\n\n12. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ\n\n12.1. Настоящий Договор вступает в силу с даты подписания и действует до полного исполнения Сторонами своих обязательств.\n\n12.2. Все изменения и дополнения к настоящему Договору оформляются в письменной форме и подписываются уполномоченными представителями Сторон.\n\n12.3. Настоящий Договор составлен в двух экземплярах, имеющих равную юридическую силу, по одному для каждой из Сторон.\n\n13. РЕКВИЗИТЫ И ПОДПИСИ СТОРОН\n\nЗаказчик:\nООО «Памир Трейд»\nИНН: [уточнить: ИНН]\nСвидетельство о государственной регистрации №: [уточнить: номер свидетельства]\nЮридический адрес: [уточнить: адрес]\nРасчётный счёт: [уточнить: номер счёта]\nБанк: [уточнить: наименование банка]\nБИК: [уточнить: БИК]\nТелефон: [уточнить: телефон]\nЭлектронная почта: [уточнить: адрес электронной почты]\n\nРуководитель / представитель: _________________________ / [уточнить: Ф.И.О.] /\nМ.П.\n\nИсполнитель:\nООО «Сомон Диджитал»\nИНН: [уточнить: ИНН]\nСвидетельство о государственной регистрации №: [уточнить: номер свидетельства]\nЮридический адрес: г. Душанбе, [уточнить: адрес]\nРасчётный счёт: [уточнить: номер счёта]\nБанк: [уточнить: наименование банка]\nБИК: [уточнить: БИК]\nТелефон: [уточнить: телефон]\nЭлектронная почта: [уточнить: адрес электронной почты]\n\nРуководитель / представитель: _________________________ / [уточнить: Ф.И.О.] /\nМ.П."}};
